import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const q=JSON.parse('{"title":"科技爱好者周刊 #415 提炼：3D 版《看不见的城市》｜Deno 谢幕","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/weekly-415-analysis.md","filePath":"topics/ai-system-architecture/weekly-415-analysis.md"}'),e={name:"topics/ai-system-architecture/weekly-415-analysis.md"};function g(d,t,a,i,u,l){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="科技爱好者周刊-415-提炼-3d-版《看不见的城市》-deno-谢幕" tabindex="-1">科技爱好者周刊 #415 提炼：3D 版《看不见的城市》｜Deno 谢幕 <a class="header-anchor" href="#科技爱好者周刊-415-提炼-3d-版《看不见的城市》-deno-谢幕" aria-label="Permalink to &quot;科技爱好者周刊 #415 提炼：3D 版《看不见的城市》｜Deno 谢幕&quot;">​</a></h1><blockquote><p>来源：阮一峰《科技爱好者周刊》第 415 期（封面：湖北咸宁梓山湖度假区美术馆） 原文链接：<a href="https://github.com/ruanyf/weekly/blob/master/docs/issue-415.md" target="_blank" rel="noreferrer">https://github.com/ruanyf/weekly/blob/master/docs/issue-415.md</a> 直链：<a href="https://raw.githubusercontent.com/ruanyf/weekly/master/docs/issue-415.md" target="_blank" rel="noreferrer">https://raw.githubusercontent.com/ruanyf/weekly/master/docs/issue-415.md</a> 抓取校验：2026-10-20 抓取成功，正文 380 行 / 20,321 字节，含标题「科技爱好者周刊（第 415 期）：3D 版《看不见的城市》」✅ 外部核实：Quesma Blog《I gave Opus 5.5 one prompt and six hours to visualize Invisible Cities》（Piotr Migdał，2026-10-07）+ Deno 官方博客《Deno is joining Cloudflare》（Ryan Dahl，2026-10-09）+ Ryan Dahl 在 Hacker News 的原帖回复（HN item 50023277，账号 rough-sea）+ lightbulbcomputer.com（Guillaume Ardaud，2026-09）+ DeskMind《三周、二十轮训练、600 美元》（gxcsoccer，2026-10-04）+ Amos B. Batto《Will Linux phones become a viable alternative…》（2026-10-05）+ antonz.org《Write the damn code》（2025-09-26）+ GitHub API 实测全部工具仓库（2026-10-20） 状态：已落盘 · 周刊监控第 6 期（上一期 #414）</p></blockquote><hr><h2 id="一、本期主文" tabindex="-1">一、本期主文 <a class="header-anchor" href="#一、本期主文" aria-label="Permalink to &quot;一、本期主文&quot;">​</a></h2><h3 id="_1-3d-版《看不见的城市》-一次-prompt-测出两个模型的-审美" tabindex="-1">1. 3D 版《看不见的城市》：一次 prompt，测出两个模型的&quot;审美&quot; <a class="header-anchor" href="#_1-3d-版《看不见的城市》-一次-prompt-测出两个模型的-审美" aria-label="Permalink to &quot;1. 3D 版《看不见的城市》：一次 prompt，测出两个模型的&quot;审美&quot;&quot;">​</a></h3><p><strong>原文主张（阮一峰）</strong></p><ul><li>卡尔维诺《看不见的城市》里的 55 座城市<strong>没有图片或模型，只有文字描述</strong>（故名&quot;看不见&quot;），比如&quot;艾琳&quot;：站在高地探身外望，&quot;透过澄澈的空气，它远远在你下面展开一片浅红……如果晚上有雾，朦胧的光线会像吸满牛奶的海绵一样涨起来。&quot;</li><li>有人把这些描述<strong>输入 AI</strong>，为 55 座城市建了<strong>可视化的 3D 版本</strong>，并用 <strong>GPT-6 Astra</strong> 与 <strong>Claude Opus 5.5</strong> 两个模型对比。</li><li>结论：<strong>Claude Opus 5.5 远比 GPT-6 Astra 好</strong>。Astra 生成的 55 个城市&quot;看上去都差不多&quot;，看不出&quot;万家灯火&quot;的意境；Opus 5.5 忠实再现了原文意象，甚至生成了坐在广场边的人群（伊希多拉）。</li><li>周刊还补了两位网友的 three.js 作品：<a href="https://github.com/billpwchan/sakura-fantasy" target="_blank" rel="noreferrer">桜幻想</a>（坐摇橹船漂在樱花河道，可切四季/早晚/晴雨雪）、<a href="https://github.com/billpwchan/neon-zenith" target="_blank" rel="noreferrer">赛博九龙</a>（对香港九龙半岛建模，还原生成 <strong>9373 栋楼</strong>）。并点出这类项目的共同缺点：<strong>体积太大、页面加载很慢</strong>。</li></ul><p><strong>外部核实（把转述钉成事实）</strong></p><p>一手原文是 Quesma 博客，作者 <strong>Piotr Migdał</strong>，2026-10-07。周刊转述准确，以下是更精的版本：</p><table tabindex="0"><thead><tr><th>项目</th><th>核实结果</th></tr></thead><tbody><tr><td>使用的 prompt</td><td>✅ 原文原句：<strong>&quot;Make a three.js (pnpm) visualization of all Invisible Cities by Italo Calvino. Don&#39;t ask questions, it is a one-shot task. You have 6h of work, use it until it becomes a masterpiece.&quot;</strong> —— 关键词是 <strong>one-shot（一次成型）+&quot;用满 6 小时直到成为杰作&quot;</strong></td></tr><tr><td>GPT-6 Astra（在 Codex 里）</td><td>✅ <strong>53 分钟、medium effort、约 $10 API 费用</strong>。作者点评：有&quot;AI 设计垃圾（design slop）&quot;——加了一堆概念和注释，却不检查是否真需要；还有一些&quot;废话式&quot;文案（对无障碍有意义，但不该原样展示）；<strong>风格上反而像在模仿 Claude</strong>（米色背景、<code>05</code> 这类数字编号）</td></tr><tr><td>Claude Opus 5.5（在 Claude Code 里）</td><td>✅ <strong>实际只用了 1 小时 25 分钟</strong>（作者给了 6 小时，它自己说&quot;用了大约一半，剩下的打磨收益递减&quot;）；<strong>6 个子代理并行，折算约 7 agent-hours，约 $74 API 费用</strong>。作者用&quot;agentic time dilation（智能体时间膨胀）&quot;解释这个折算</td></tr><tr><td>作者的态度</td><td>✅ 原话很值得记：他本想骂 Opus &quot;早收工&quot;，结果一看成品就&quot;mesmerized（着迷）&quot;了 —— <strong>&quot;如果这就是天花板，那这个天花板很高。&quot;</strong> 收尾一句是他的自问：<strong>&quot;我在创造交互媒体这件事里的位置在哪？&quot;</strong></td></tr><tr><td>作者并非新玩家</td><td>✅ 他 2019 年就用<strong>当时的 GPT-2</strong> 做过&quot;为故事表演生成城市&quot;的小项目 —— 所以这个对比是<strong>同一作者、同一命题、跨 7 年模型</strong>的对照，不是随手试玩</td></tr><tr><td>九龙 9373 栋楼</td><td>⚠️ 周刊数字，未独立核实。仓库实测见工具表（<code>neon-zenith</code> 48★，描述确实提到 Blender 烘焙的香港夜市 + 程序化巨型城市）</td></tr></tbody></table><p><strong>我的评注</strong></p><ol><li><strong>这是一份&quot;最强&quot;的 prompt 即作品实验，但它的价值不在&quot;AI 很厉害&quot;，而在它测的东西变了</strong>：两个模型都&quot;worked, end-to-end&quot;——<strong>都跑通了</strong>。区别不在&quot;能不能生成 3D&quot;，而在<strong>懂不懂原文的意境</strong>（万家灯火 / 像吸满牛奶的海绵升起的光）。也就是说，<strong>当能力跨过某个阈值，区分度从&quot;能不能做&quot;迁移到了&quot;有没有判断力/审美&quot;</strong>。这正是 #414 主线的续集：Jev 把判断压成一个浮点数、代价是把依据藏起来；本期则是<strong>判断力（审美）还藏不住</strong>——Astra 的&quot;55 个城市都一样&quot;就是判断力缺失的可见形态。</li><li><strong>成本结构值得单独记一笔</strong>：<strong>$10 vs $74，7 倍差价换&quot;懂不懂意境&quot;</strong>。而且贵的那次反而<strong>用时更短</strong>（1h25m vs 53m&quot;机器时间&quot;看似接近，但 Opus 靠 6 个并行子代理把墙钟时间压下来了）。这条和库内 <code>llm-cache-pricing.md</code>（Token 定价）、<code>ai-industry-2026-q3-knowledge.md</code> 是一条线：<strong>当生成变廉价，&quot;品味&quot;成了唯一还贵的商品</strong>。</li><li><strong>作者那句自问是本期最诚实的一句</strong>：&quot;我在创造交互媒体这件事里的位置在哪？&quot; —— 这与 #413 的&quot;代码即债务/糊状千层面&quot;、#412 的&quot;价值向验证与注意力两端迁移&quot;完全同构：<strong>实现贬值，人的位置只能往上游（提问、判断、取舍）或下游（验证、策展）迁移。</strong></li></ol><h3 id="_2-ai-的-3d-建模-three-js-正在变成一个内容品类" tabindex="-1">2. AI 的 3D 建模：three.js 正在变成一个内容品类 <a class="header-anchor" href="#_2-ai-的-3d-建模-three-js-正在变成一个内容品类" aria-label="Permalink to &quot;2. AI 的 3D 建模：three.js 正在变成一个内容品类&quot;">​</a></h3><p>周刊把 3D 建模单列一节，指出：<strong>大模型已具备很强的 3D 建模能力</strong>，这类项目统一用 <strong>three.js</strong> 生成虚拟场景、在浏览器里呈现（可缩放/旋转/移动），统一缺点是<strong>体积大、加载慢</strong>。</p><ul><li>本知识库实测确认：<code>three.js</code> 在本库<strong>此前零命中</strong>（首次由本期引入）——这是一个<strong>新主题入口</strong>，与 <code>topics/design/</code>（极简主义、负空间）是先天的邻居。</li></ul><p><strong>我的评注</strong></p><ul><li>从《看不见的城市》到《桜幻想》到《赛博九龙》，本期的这一簇其实说明一件事：<strong>&quot;复刻一个已有的事物&quot;正在变成 AI 的日常动作</strong>——城市（九龙）、小说里的城市、季节与天气、甚至 1995 年的游戏（见下文《仙剑奇侠传》）。这与本期工具栏的 <strong>REA（逆向工程复刻二进制）</strong>、<strong>ts-rust（重写 tsc）</strong> 是同一件事的五种变体。<strong>当&quot;复刻&quot;的成本趋近于零，源码本身就不再是护城河，判断力才是。</strong></li><li>但&quot;体积大、加载慢&quot;这条不要轻轻放过：<strong>它暴露了&quot;AI 生成 = 质量债&quot;的另一种形态</strong>——模型能一次性产出<strong>功能正确但工程臃肿</strong>的东西。这跟 #413 的&quot;糊状千层面（分层＝可替换）&quot;是同一个诊断：<strong>生成便宜 ≠ 维护便宜。</strong></li></ul><h3 id="_3-灯泡计算机-未来的电脑可能是一盏灯泡" tabindex="-1">3. 灯泡计算机：未来的电脑可能是一盏灯泡 <a class="header-anchor" href="#_3-灯泡计算机-未来的电脑可能是一盏灯泡" aria-label="Permalink to &quot;3. 灯泡计算机：未来的电脑可能是一盏灯泡&quot;">​</a></h3><p><strong>原文主张（阮一峰）</strong></p><ul><li>有人提出未来电脑可能是<strong>一个灯泡</strong>：用<strong>计算机视觉 + 投影</strong>技术，通过灯泡看到 360 度场景，也能把内容投射到各处物体上。烧菜时把菜谱投到对面墙上；可手势/语音交互；手指着书页就能做文字识别；地图/相册/游戏投在桌面上；对着墙操作就能控制家电；了解地理信息就把地点和菜单投到挂壁地图上。</li></ul><p><strong>外部核实</strong></p><p>原文是 Guillaume Ardaud 2026-09 发布的《The Lightbulb Computer》（lightbulbcomputer.com）。比周刊完整得多：</p><ul><li><strong>形式选择的理由</strong>：灯泡做成&quot;大号灯泡&quot;形状，可以装进便携灯座带走，也可以<strong>拧进任何墙面/天花板的爱迪生灯座</strong>做室内常驻。作者点明两个理由：① <strong>天花板是俯瞰整个房间、并且随处可投的最佳视角</strong>；② <strong>灯泡灯座是近乎全球通用的标准</strong>。</li><li><strong>反面立论（周刊没提，但更重要）</strong>：作者的靶子<strong>不是屏幕，而是&quot;眼镜式计算&quot;</strong>（VR/MR/AR）。他反对的理由很具体：<strong>眼镜要贴在脸上</strong>——会干扰发型/化妆/首饰/眼镜隐形眼镜；<strong>形态受限于&quot;必须又小又轻&quot;</strong>，于是功耗/算力/散热全被锁死；<strong>最要命的是它反社交</strong>——&quot;每个人必须有自己的设备，还得彼此兼容，才有共享体验&quot;。他配了一张&quot;营销图 vs 真实室内景象&quot;的对比来嘲讽。</li><li><strong>作者自陈的诚实边界</strong>：所有演示视频<strong>来自一个&quot;真实但笨重&quot;的原型装置</strong>，明确声明<strong>没有视频剪辑、没有特效、没有 AI 生成</strong>。以及：<strong>现在还不能做消费版</strong>，但也&quot;不远了&quot;；<strong>隐私必须是一等公民</strong>——走端上处理、硬件护栏（只有用户激活才开摄像头 + 硬接线指示灯 + 物理遮挡）。</li><li><strong>他引的先例</strong>：I/O Bulb、LuminAR（研究项目）、Humane Pin、Dynamicland / Folk Computer（社区项目）——并指出这些<strong>都没覆盖&quot;个人计算&quot;</strong>（家里/工位上用电脑做的事），那里才是真正有重设计空间的地方。</li></ul><p><strong>我的评注</strong></p><ol><li><strong>&quot;换个形态&quot;比&quot;加个能力&quot;更值钱</strong>——这个项目最聪明的地方不是投影 + CV（都是现成技术），而是<strong>把设备拧进一个已经存在了 100 年的物理标准（爱迪生灯座）里</strong>。这是<strong>寻找既有接口而不是发明新接口</strong>的经典手法。<strong>把它和本期的 Deno 放在一起看，反差极其鲜明</strong>：Deno 死于&quot;复刻 Node&quot;，灯泡计算机活于&quot;搭上爱迪生灯座&quot;——<strong>同样是&quot;寄生在既有标准上&quot;，一个是被引力吸死（模仿行为），一个是借力起飞（复用物理接口）。</strong> 差别在于：<strong>模仿别人的行为 = 永远落后一步；复用别人的接口 = 立刻获得整个生态。</strong></li><li><strong>这是本库 <code>topics/design/</code> 的直接素材</strong>：作者的核心论证&quot;屏幕给了一个**过度简化（reductive）**的世界观、让人忽略周围&quot;，与 <code>minimalism-death-of-detail.md</code>、<code>eastern-negative-space.md</code> 里&quot;注意力被单一矩形绑架&quot;是同一家族的问题意识——<strong>一个从美学角度批判（极简掏空细节），一个从交互角度批判（矩形框住世界）。</strong></li></ol><h3 id="_4-deno-项目结束了" tabindex="-1">4. Deno 项目结束了 <a class="header-anchor" href="#_4-deno-项目结束了" aria-label="Permalink to &quot;4. Deno 项目结束了&quot;">​</a></h3><p><strong>原文主张（阮一峰）</strong></p><ul><li>上周 Deno <strong>宣布被 Cloudflare 收购</strong>，未来一年只发布<strong>错误修复和安全更新</strong>，然后就彻底结束。</li><li>周刊的复盘很锋利：Deno 诞生时豪言要改掉 Node.js 的&quot;臃肿依赖、无权限控制、不支持 TypeScript&quot;等弊端，各种创新&quot;或多或少接近了这些目标，但最终还是黯然收场&quot;。</li><li><strong>&quot;它的结局其实在 2024 年就注定了&quot;</strong>——那年它发布 2.0 版，<strong>大规模兼容 Node.js</strong>，意味着它&quot;对于走自己的路已经丧失了信心&quot;，不再打算打败 Node.js，而是让用户不改代码就能跑在它上面。&quot;但是，我已经能用 Node.js 运行代码了，何必改用一个模仿 Node.js 行为的运行时呢？&quot;</li></ul><p><strong>外部核实</strong></p><ul><li>✅ Deno 官方博客《Deno is joining Cloudflare》，<strong>2026-10-09，作者 Ryan Dahl 本人</strong>。口径比周刊完整：<strong>整个 Deno 团队加入 Cloudflare</strong>；未来开发重心转到<strong>共享平台</strong>（与 Workers、Durable Objects 团队合并）而不是继续维护独立的运行时与托管服务；讲清了技术路线 <strong>Deno → Deno Deploy → celld</strong>（celld 基于 Cloudflare Workers 编程模型，<strong>只靠对象存储做协调与持久化</strong>）。博客原话：希望让这套编程模型成为&quot;构建服务器的默认方式，无论跑在 Cloudflare 网络还是你自己的基础设施上&quot;。</li><li>✅ Ryan Dahl 在 Hacker News 的回复（账号 <code>rough-sea</code>，HN item <strong>50023277</strong>）被周刊引用且翻译准确。原文关键句： <blockquote><p>&quot;It&#39;s a joint decision and I agree with it. I&#39;m most invested in its success and have put the most work into it - and I no longer think it&#39;s where I can do the most important work. There are some good ideas in Deno and it&#39;s well engineered - but it ultimately is not solving big problems. <strong>It has been sucked into the gravity well of node compatibility, which forces it to behave exactly as Node does. Why reimplement Node? It works.</strong> Marginal performance or UX or security benefits are not enough. <strong>I&#39;m interested in building powerful new abstractions.</strong>&quot;</p></blockquote></li><li>✅ <strong>两条周刊没写、但对用户重要的补充</strong>：① <strong>&quot;每月发一次版本、持续一年，Deno 保持 MIT 许可&quot;</strong>（Dahl 原话：&quot;We&#39;ll ship monthly releases for a year, and Deno stays MIT-licensed. If people want to carry it forward, I&#39;d like that.&quot;）——即<strong>不是关停，是把接力棒递出去</strong>；② Dahl 明确表态&quot;我想做的是新的抽象（powerful new abstractions）&quot;，并把 celld 定义为&quot;<strong>不是换一套文件系统/网络 API，而是服务器开发的整个新模型</strong>&quot;。</li><li>⚠️ 周刊&quot;只发布错误修复和安全更新&quot;的措辞<strong>比原文更绝对</strong>：Dahl 说的是<strong>每月版本 + MIT + 谁想接手他都乐意</strong>。这个差别影响判断——<strong>Deno 不是&quot;死了&quot;，是&quot;被放弃了增长、但没被抛尸&quot;</strong>。</li></ul><p><strong>我的评注</strong></p><ol><li><strong>这是&quot;抽象层竞争&quot;的最干净的一课，也是本期的枢纽</strong>：Dahl 的证词几乎是把 #413 的&quot;AI 先吃掉翻译层 → 共享实现贬值&quot;用运行时语言重讲了一遍——<strong>当一个&quot;更好的实现&quot;必须靠模仿既有实现来获取用户时，它就已经输了</strong>，因为在&quot;实现&quot;这个维度上，先发者永远有网络效应。<strong>&quot;Marginal performance or UX or security benefits are not enough&quot;</strong> 这句话值得单独抄下来：<strong>在成熟生态里，边际改进不构成迁移理由。</strong></li><li><strong>把它接回库内</strong>：<code>gear-shaft-org-reinvention.md</code>（工业革命&quot;砍天轴&quot;→ 别外挂、要推倒重来）说的是<strong>别只换零件</strong>；Deno 的教训说的是<strong>别只做更快的零件</strong>。两者合起来是本库一条清晰的判断线：<strong>真正的机会在新抽象，不在&quot;更好的旧抽象&quot;。</strong></li><li><strong>对用户的直接含义</strong>：这条与工具栏的 <strong>ts-rust（用 AI 重写 tsc）</strong> 构成一个漂亮的对照题 —— <strong>同样是&quot;重新实现一个既有编译器&quot;，一个被生态引力吸死，一个却能靠 AI 把成本打到地板价。</strong> 区别是：<strong>Node 兼容性是&quot;用户的迁移成本&quot;，而 tsc 兼容性是&quot;可自动验证的等价性&quot;</strong>。<strong>能被自动判定等价的重写，才有机会绕过引力。</strong> 这条值得记进方法论。</li></ol><hr><h2 id="二、文章" tabindex="-1">二、文章 <a class="header-anchor" href="#二、文章" aria-label="Permalink to &quot;二、文章&quot;">​</a></h2><ol><li><p><strong><a href="https://deskmind.dev/zh/blog/launch/" target="_blank" rel="noreferrer">我如何用 600 美元后训练出一个 Jev 式决策模型</a></strong>（中文，DeskMind，作者 gxcsoccer，2026-10-04）—— <strong>本期最值得读的一篇，且是对 #414 主文（Jev）的直接回应。</strong></p><p><strong>已核实的关键事实（一手原文）</strong>：</p><ul><li><strong>Jev 发布第二天就开工</strong>，&quot;三周、二十来轮训练、约 600 美元&quot;。训出两个模型跑在本地 Mac 上：<strong>Eyes</strong>（4B 视觉定位，先 SFT 再 RL）+ <strong>Brain</strong>（<strong>Qwen3.5 的 0.8B 和 4B + LoRA，Apple 芯片上用 8 位 MLX 跑</strong>）。</li><li><strong>接口和 Jev 一样，都是 <code>/v1/systemone</code></strong> —— 即<strong>主动复刻了 Jev 的&quot;决策模型&quot;接口</strong>，但<strong>拒绝把云端依赖塞进本地 agent 的中间</strong>（&quot;它只有云端接口，而我不想在一个本地 agent 的正中间放一个云端依赖。那就自己训一个&quot;）。</li><li><strong>五个组件全部开源</strong>：Eyes / Brain / Hands（macOS harness）/ Mac App / Bench。</li><li><strong>作者的三个&quot;最值钱&quot;发现</strong>：① <strong>想让模型学会&quot;问&quot;，得先让 harness 提供&quot;问用户&quot;这个选项</strong>；② <strong>&quot;完成&quot;要靠检查结果，不能靠模型自己说</strong>；③ <strong>他把训练标签平滑到 0.95，导致 0.8B 的把握全挤到门槛边上，70% 的步骤只好交给慢的 4B</strong> —— 一个自己埋的坑。</li><li><strong>混合路由机制</strong>：0.8B 先答，<strong>把握低于 0.96 或风险高 → 交给 4B 重答</strong>；harness 发现两个选项都讲得通 → <strong>在选项里加上&quot;问用户&quot;</strong>，模型就停下来问。</li><li><strong>成绩（带前提）</strong>：自建真实桌面 bench v25 <strong>39/39 结果正确、0 次&quot;没做完就说完成&quot;</strong>；ScreenSpot-Pro（Eyes）<strong>App 实际设置下 50.9%</strong>，<strong>GPU + 原始分辨率下 67.7%</strong>；JevBench v1.4.2 公开题 <strong>4B 得 0.835（193/231）</strong>。作者<strong>自己主动打折</strong>：&quot;39/39 听着比实际好&quot;（只 13 个任务×3 次、单一机器、有一个任务模型写对了文件却一直不报完成而耗尽 20 步）。</li><li><strong>速度诚实交代</strong>：0.8B 一次决策 ~0.5 秒，但 70% 步骤走 4B（每次 ~3.6 秒），<strong>中位数 2.85 秒、最慢 5% 近 10 秒</strong>。</li><li><strong>它还搞不定</strong>：超过四五行的表格、照着收据照片填报销单。</li></ul><p><strong>我的评注</strong>：这篇把 #414 的关键争论<strong>用工程回答了一遍</strong>。Willison 批 Jev&quot;是黑箱回归、只给你一个浮点数&quot;——DeskMind 的答案是：<strong>黑箱不可怕，&quot;拿不准就问&quot;才是真正的安全阀</strong>，而且这个安全阀<strong>必须同时训在模型里、也留在 harness 里</strong>（&quot;少了哪一边都做不成&quot;）。作者自己总结的那句应该进本库方法论：<strong>&quot;模型塑造 harness，harness 反过来塑造模型&quot;</strong> —— 这与库内 <code>brain-self-evolution.md</code>（回放评测：被评对象与评估器共享同一接口）、<code>deepseek-harness-agent-runtime.md</code>（harness 才是竞争焦点）是同一结论的三个独立到达。<strong>另外注意：作者用 $600 就复刻了 #414 里被炒成&quot;新范式&quot;的接口</strong>——这本身就是本周刊两期合起来最硬的一条判断：<strong>接口一旦公开可模仿，它的「范式」溢价就只剩下时间差。</strong></p></li><li><p><strong><a href="https://mp.weixin.qq.com/s/RL8w75YfXQrRubSLJHnSVA" target="_blank" rel="noreferrer">给导弹写代码，为什么严禁使用动态内存分配？</a></strong>（中文）—— 讲洛克希德·马丁军工 C 语言编码规则里&quot;严禁 <code>malloc</code>/<code>free</code>/<code>new</code>/<code>delete</code>&quot;。</p><ul><li>⚠️ <strong>原文为微信公众号，本机无法抓取，未能核实原文论据</strong>。以下<strong>是编者补充的通用工程原理，不是对该文的复述</strong>：禁用动态分配的核心是<strong>确定性与可分析性</strong>——① 避免<strong>内存碎片</strong>；② 避免<strong>分配失败</strong>这一&quot;必须处理但难以穷尽&quot;的分支；③ 让<strong>最坏执行时间（WCET）<strong>可静态分析；④ 让</strong>内存占用在编译期就能核算</strong>。这与 MISRA C、JSF C++（航空）等标准的取向一致。</li><li><strong>我的评注</strong>：这条对用户的真实价值不在军工，而在**&quot;实时/嵌入式系统的第一条纪律是消灭不确定性&quot;**。它与库内 <code>energysim/</code>（PyPSA 求解器）、<code>wind-energy/</code> 里的数据管道有同构之处：<strong>凡是&quot;必须在限定时间内给出结果&quot;的系统，都要先问&quot;哪里会出现不可控的失败分支&quot;。</strong> 生成式 AI 恰恰相反——它靠&quot;每次都可能有意外&quot;工作。<strong>两者不能混着用。</strong></li></ul></li><li><p><strong><a href="https://railcode.dev/blog/vibe-coded-website" target="_blank" rel="noreferrer">如何让 AI 网页看起来像设计师作品</a></strong>（英文）—— 作者介绍怎么让 AI 生成的网页看起来像真人设计的。（⚠️ 未抓取原文）</p></li><li><p><strong><a href="https://amosbbatto.wordpress.com/2026/10/05/linux-phones-alternative/" target="_blank" rel="noreferrer">为什么没有 Linux 手机</a></strong>（英文，Amos B. Batto，2026-10-05，CC BY 4.0）—— <strong>⚠️ 本条周刊的转述有&quot;归因压扁&quot;问题，值得单独记一笔。</strong></p><ul><li><strong>周刊的版本</strong>：主要原因是没有 Linux 的 SOC——苹果/安卓的芯片可以集成在一起，Linux 只能逐个添加单芯片，导致<strong>体积大、耗能多、成本高、性能差</strong>；现在仅存的选择是<strong>瑞芯微 RK3588S</strong>。</li><li><strong>原文实际结构（15 节）</strong>：① SoC 困境是&quot;弱但长寿 vs 强但短命&quot;；② <strong>&quot;RK3588S 改变了游戏规则&quot;</strong>；③ 新增&quot;用高通 IoT SoC 做 Linux 手机&quot;这条路；④ 用 Android 内核的问题；⑤ 基于 Android 的 Linux 手机因支持周期更长而更可行；⑥-⑦ 软件曾是 Librem 5 的主要难题、Phosh 的成功；⑧ 发行版接纳移动界面；⑨ PINE64 想绕过软件开发成本；⑩ 热情消退；⑪ Jolla 证明仍有需求；⑫ 移动产业正在关闭 AOSP 替代方案；⑬ <strong>现在可能有三类 Linux 手机</strong>；⑭ <strong>&quot;真正的障碍是那些公司&quot;</strong>。</li><li><strong>原文的结论与周刊相反</strong>：<strong>&quot;现在 SoC 和软件都不再是障碍，真正的障碍是做和卖这些手机的公司。&quot;</strong> 具体点出 PINE64 因 <strong>RAM/eMMC 涨价</strong>暂停大部分设备生产、且不愿为内核开发付钱；Purism 计划 Librem 5 v2（2026-07 通讯、准备众筹&quot;超 200 万美元&quot;），但<strong>因拒绝给 600 名取消订单用户退款（不到 40 万美元）而声誉受损</strong>。</li><li><strong>我的评注</strong>：这是本库反复记录的**&quot;二手转述失真&quot;的又一形态**——不是数字错，而是<strong>把&quot;技术障碍已解除、真正的瓶颈是商业模式&quot;压缩成了&quot;技术障碍还在（没有 SoC）&quot;</strong>。周刊的版本让人得出&quot;等芯片就好了&quot;的（错误）结论，原文恰恰说芯片问题<strong>已经解决</strong>、卡在<strong>公司是否愿意为软件付费</strong>。<strong>结论方向相反。</strong> 顺带一提，原文明说 RK3588S 是&quot;几年前的产品但做普通用途够用&quot;——<strong>周刊把&quot;唯一可行的折中&quot;讲成了&quot;唯一仅存的选择&quot;，语气不同，含义也不同。</strong></li></ul></li><li><p><strong><a href="https://lemire.me/blog/2026/09/18/how-did-amd-ryzen-get-50-faster-in-two-years/" target="_blank" rel="noreferrer">AMD 处理器如何在两年内速度提升 50%？</a></strong>（英文，lemire.me，2026-09-18）—— AMD Ryzen 7 系列，<strong>2024 年型号比 2022 年型号性能得分 +50%</strong>，本文分析怎么做到的。（⚠️ 未抓取原文）</p><ul><li><strong>我的评注</strong>：这条纠正一个流行错觉——&quot;CPU 这些年进展不大&quot;。对用户的实际含义：<strong>自托管/本地推理的硬件底座仍在快速变好</strong>，与本期 DeskMind（本地 0.8B/4B）、bg2x（浏览器本地超分）构成&quot;本地算力可行&quot;的一组信号。</li></ul></li><li><p><strong><a href="https://asheradeniyi.com/2026/04/10/how-to-build-wealth-as-a-career-person/" target="_blank" rel="noreferrer">职场人士如何积累财富</a></strong>（英文，Asher Adeniyi，2026-04-10）—— 非技术文。</p><ul><li><strong>已核实的核心论点</strong>：反&quot;只有创业才能致富&quot;；核心区分是**&quot;职业是引擎，不是目的地&quot;**——&quot;<strong>收入是为你工作而流向你的东西；财富是你拥有、并在薪水付清后仍继续为你服务的东西</strong>&quot;。引用 <strong>Morgan Housel《The Psychology of Money》</strong>：&quot;<strong>财富是你没看见的东西</strong>&quot;（看得见的车可能是贷款的，看不见的组合才在创造安全）。两条任务：<strong>① 提高你工作的价值；② 留住并投资你收到的价值中有意义的一部分。</strong> 文中给了一条可核实数据：<strong>世界银行估计，多受一年教育的全球平均私人回报率约每年 9%</strong>。</li><li><strong>我的评注</strong>：这条与库内 <code>topics/career-observation/</code>（<code>ai-leverage-playbook.md</code>、<code>reverse-ability-ai-era.md</code>）直接对位。<strong>在 AI 让&quot;实现&quot;贬值的年份，这条建议的方向恰好一致：把收入换成资产（而不是换成生活方式），把职场精力换成&quot;可信度与判断力&quot;（而不是&quot;工时&quot;）。</strong> 与 #415 主文的&quot;审美/判断力才是唯一还贵的商品&quot;是同一枚硬币。</li></ul></li></ol><hr><h2 id="三、工具-含-github-api-实测与接入评估" tabindex="-1">三、工具（含 GitHub API 实测与接入评估） <a class="header-anchor" href="#三、工具-含-github-api-实测与接入评估" aria-label="Permalink to &quot;三、工具（含 GitHub API 实测与接入评估）&quot;">​</a></h2><p>全部用 GitHub API 实测（2026-10-20）。★ = 对用户现有工作流（知识库外脑 / 飞书 / 风电与 PyPSA 仿真 / DSH / 自托管）的接入价值。</p><table tabindex="0"><thead><tr><th>工具</th><th>实测数据（2026-10-20）</th><th>一句话</th><th>接入价值</th></tr></thead><tbody><tr><td><a href="https://github.com/morluto/rea" target="_blank" rel="noreferrer">REA</a></td><td>TypeScript · <strong>★337,461</strong> · <strong>85,200 fork</strong> · MIT · 建 2026-04-14 · 当日仍在推</td><td>用 agent 做<strong>逆向工程</strong>：从 app 行为一路到原生二进制，AI 重写出版本</td><td>⭐ <strong>中（观察级）</strong>。<strong>⚠️ 周刊写&quot;近 20 万颗星&quot;，实测 33.7 万</strong>——若属实，这已是 GitHub 历史级项目量级，star 增速本身是数据点。<strong>值得注意：其 topics 含 <code>cordis</code></strong> —— 与库内 DSH 的 Cordis 插件内核同名，值得另查是否同源。概念价值高（&quot;软件可否被复刻&quot;），但对本库无直接接入</td></tr><tr><td><a href="https://synthid.com/" target="_blank" rel="noreferrer">SynthID 检测器</a></td><td>网站（非仓库）· 谷歌官方</td><td>上传文件判断是否含 <strong>SynthID</strong> 水印，从而识别 AI 生成</td><td>中。<strong>内容溯源</strong>工具。外脑里存了大量 AI 生成/拼接内容，可用于抽查来源。⚠️ 只认谷歌自己的水印，对别家生成的内容<strong>必然漏判</strong>（不能反推&quot;没有水印 = 人类所作&quot;）</td></tr><tr><td><a href="https://github.com/pingdotgg/ts-rust" target="_blank" rel="noreferrer">ts-rust</a></td><td>Rust · <strong>★1,376</strong> · MIT · <strong>建 2026-10-07</strong>（2 周龄）· 活跃</td><td><strong>AI 实现的 Rust 版 TypeScript 编译器</strong>（TypeScript 7 编译器 tsc 的实验性 Rust 移植），号称 100% 兼容</td><td>⭐ <strong>中（工程思路）</strong>。全库应用面窄，但<strong>它是&quot;AI 复刻既有编译器&quot;的最新样本</strong>——与本期 Deno 的教训正面对照（见主文四评注 3）。⚠️ 自述&quot;experimental&quot;，别用于生产构建</td></tr><tr><td><a href="https://github.com/shaongitbd/doory" target="_blank" rel="noreferrer">Doory</a></td><td>TypeScript · <strong>★1,651</strong> · <strong>许可证 NOASSERTION</strong>（非标准）· 建 2026-10-10</td><td>浏览器里的平面设计工具，<strong>开源 Canva 替代</strong>（周刊：模板仅 10 个）</td><td>低-中。<strong>⚠️ 许可证是 NOASSERTION（自定义/未识别）= 用前必须自己读 LICENSE</strong>，这类&quot;自托管替代品&quot;最容易埋许可坑（本库老规矩：<strong>自托管先查许可证</strong>）。10 天龄 + 1.6k★ = 纯热度，别上生产</td></tr><tr><td><a href="https://github.com/Cogria-AI/HeadOrbit" target="_blank" rel="noreferrer">HeadOrbit</a></td><td>Swift · <strong>★166</strong> · MIT · 建 2026-09-13 · 推 2026-10-05</td><td>用 <strong>AirPods 内置运动传感器</strong>做头部/颈部追踪，点头摇头操作 Mac，<strong>不用摄像头</strong></td><td>中。用户的&quot;无摄像头输入设备&quot;选项（隐私友好）。⚠️ 实测描述与周刊略有差异：仓库自述是 <strong>&quot;look-away blur（走神模糊）+ 姿势提醒&quot;</strong>，周刊讲的是&quot;点头/摇头/颈部移动操作电脑&quot;——<strong>同一技术的两种用法</strong>，以仓库为准</td></tr><tr><td><a href="https://github.com/yinzhenyu-su/qrypt" target="_blank" rel="noreferrer">qrypt</a></td><td>Go · <strong>★136</strong> · MIT · 建 2026-06-22 · 活跃</td><td>把<strong>网盘挂载成本地文件夹</strong>的跨平台 CLI，<strong>端到端加密 + 快速上传</strong>，统一 S3/WebDAV/国内网盘（115/阿里云盘/百度云等）</td><td>⭐ <strong>中高（自托管/备份线）</strong>。与用户的 <strong>GitHub 备份同步</strong>需求直接相关：<strong>可做知识库的第二份异地冷备</strong>（E2E 加密这一条对它加分）。⚠️ 136★ 属小众，挂载类工具对<strong>数据安全</strong>要自行评估</td></tr><tr><td><a href="https://github.com/aozorae/EdgeSSH" target="_blank" rel="noreferrer">EdgeSSH</a></td><td>TypeScript · <strong>★296</strong> · <strong>Apache-2.0</strong> · 建 2026-09-18 · 活跃</td><td>基于 <strong>Cloudflare Workers</strong> 的轻量 WebSSH 工作台（主机管理、加密存储、SFTP、进程监控、地球可视化）</td><td>中（自托管线）。<strong>与本期 Deno 同一条&quot;Cloudflare 平台化&quot;主线</strong>：Workers 正在变成运行业务的默认底座（Dahl 本人也这么说）。⚠️ 把 SSH 凭据托管在 Cloudflare 上是<strong>信任边界问题</strong>，用前想清楚</td></tr><tr><td><a href="https://github.com/vicanso/charts-rs" target="_blank" rel="noreferrer">charts-rs</a></td><td>Rust · <strong>★402</strong> · Apache-2.0 · <strong>建 2023-03-28</strong>（旧项目）</td><td>Rust 图表库，<strong>不依赖浏览器/Node.js</strong>，直接产出 SVG 和图片，语法借鉴 ECharts</td><td>⭐ <strong>中（风电/能量仿真出图）</strong>。<strong>无需 JS 运行时就能出图</strong>这一点对<strong>服务器端批量出图</strong>（如 PyPSA 结果批量可视化、日报图表）很有用，可绕开&quot;必须装 Playwright/浏览器&quot;的依赖。老项目 = 稳定性相对可信</td></tr><tr><td><a href="https://github.com/joshlin2201/itspaint" target="_blank" rel="noreferrer">ItsPaint</a></td><td>Swift · <strong>★60</strong> · MIT · 建 2026-07-29</td><td>macOS 开源画板，适合给截图做标注</td><td>中低（体验类）。<strong>架构值得看</strong>：绘图引擎是独立无依赖的 Swift 包 <strong>PaintKit</strong>（本库 <code>topics/quality-products/</code> 的素材：&quot;把引擎抽成可复用包&quot;是产品化正路）</td></tr><tr><td><a href="https://github.com/icloudza/caplo" target="_blank" rel="noreferrer">Caplo</a></td><td>Swift · <strong>★213</strong> · <strong>NOASSERTION</strong> · 建 2026-09-08 · 推 2026-10-12</td><td>开源 macOS 录屏，<strong>点击时自动放大镜头、画面跟随鼠标</strong></td><td>中。做<strong>演示/教程录屏</strong>时的体验优化；配合 DeskMind 那类&quot;看屏幕操作&quot;的评估也实用。⚠️ 许可证未识别，商用前先读 LICENSE</td></tr><tr><td><a href="https://github.com/isixe/bg2x" target="_blank" rel="noreferrer">bg2x</a></td><td>Vue · <strong>★101</strong> · MIT · 建 2026-09-27</td><td><strong>可选不同 AI 模型的图像超分（放大）工具，最高 4×，全部在浏览器本地完成</strong></td><td>⭐ <strong>中（本地化 + 图片沉淀）</strong>。与用户的资产线（<code>assets/</code> 存图 + GitHub 附件）相关：<strong>本地处理 = 隐私可控</strong>，适合处理不便上传的内容。<strong>且它是&quot;浏览器内跑模型&quot;的又一证据</strong>（本地算力可行）</td></tr><tr><td><a href="https://envtrace.net/" target="_blank" rel="noreferrer">EnvTrace</a></td><td>网站（非仓库）</td><td>检查<strong>浏览器指纹</strong>泄漏了多少个人信息，指出问题点</td><td>中（安全自查）。与库内 <code>topics/cybersecurity/</code> 同域。适合定期自查</td></tr><tr><td><a href="https://github.com/KnifeLemon/Droidline" target="_blank" rel="noreferrer">Droidline</a></td><td>Go · <strong>★289</strong> · MIT · <strong>建 2026-10-07</strong></td><td>开源的<strong>安卓自动化</strong>：手机装 App 扫码配对，电脑写脚本操作手机，<strong>不用开 USB 调试、不用 root</strong>；topics 含 <code>ai-agents</code>、<code>adb-alternative</code></td><td>⭐ <strong>中高（手机自动化/agent 线）</strong>。<strong>免 root 的组件式方案</strong>，与本期 <code>esp32-iphone-agent</code> 是同一件事的安卓版；作者明确面向 <strong>&quot;让 AI agent 用一台手机&quot;</strong>。⚠️ 依赖无障碍服务 = 权限很大，慎用主力机</td></tr><tr><td><a href="https://github.com/onehumanbeing/esp32-iphone-agent" target="_blank" rel="noreferrer">ESP32 iPhone Agent</a></td><td>C · <strong>★3,291</strong> · MIT · <strong>建 2026-10-11</strong>（9 天，已 3.3k★）· 活跃</td><td>一块 <strong>~$7 的 ESP32-S3</strong> 插进 iPhone USB，<strong>AirPlay 当眼睛、USB HID 当手</strong>，让任意 OpenAI 兼容视觉模型操作真机；<strong>无需 Mac、无需开发者账号、无需越狱</strong></td><td>⭐⭐ <strong>高（本期硬件亮点）</strong>。<strong>&quot;用 $7 把昂贵设备变成可被 AI 驱动的对象&quot;</strong> 是极漂亮的成本结构：<strong>眼睛（AirPlay 投屏）和手（USB HID）都是设备已经提供的接口</strong>——与&quot;灯泡计算机搭爱迪生灯座&quot;是同一种聪明。⚠️ 9 天 3.3k★ = 极大热度 + 极小验证；<strong>且&quot;让 AI 操作你的主力手机&quot;是高风险权限组合</strong></td></tr><tr><td><a href="https://github.com/s3onghyun/bulchimbeon" target="_blank" rel="noreferrer">Bulchimbeon</a></td><td>Swift · <strong>★35</strong> · MIT · 建 2026-10-13</td><td>macOS 软件，<strong>只在 AI 编程代理工作时</strong>阻止 Mac 休眠（支持合盖保持唤醒、过热暂停、低电量退出）</td><td>⭐ <strong>中高（直接可用）</strong>。用户跑 Claude Code / Codex 时&quot;合盖就跑挂&quot;是真实痛点，<strong>这正是对症工具</strong>。仓库自述：<strong>&quot;No hooks, no daemon&quot;</strong>、macOS 13+。⚠️ 35★、7 天龄 —— <strong>先看代码再用，但它解决的问题很具体</strong></td></tr></tbody></table><p><strong>小结（工具层判断）</strong>：本期对用户真正有增量的是 <strong>① <code>esp32-iphone-agent</code>（$7 复用设备既有接口，思路最值钱）、② <code>bulchimbeon</code>（AI 代理跑挂 Mac 的直接解法）、③ <code>Droidline</code>（免 root 手机自动化）、④ <code>qrypt</code>（知识库异地冷备）、⑤ <code>bg2x</code>（浏览器本地超分）</strong>，外加出图线的 <strong><code>charts-rs</code>（无需 JS 运行时的服务端出图）</strong>。三条老规矩继续生效：<strong>① 自托管先查许可证</strong>（本期 <code>Doory</code>/<code>Caplo</code> 都是 NOASSERTION，必须自己读；<code>type-pal</code> 是 GPL-3.0 传染）；<strong>② 极新项目先借思路别上生产</strong>（ts-rust 2 周、Droidline 13 天、esp32-iphone-agent 9 天、Bulchimbeon 7 天）；<strong>③ 高热度 ≠ 已验证</strong>（期间实测 star 增速普遍是&quot;AI 热&quot;而非&quot;工程成熟&quot;）。</p><hr><h2 id="四、资源" tabindex="-1">四、资源 <a class="header-anchor" href="#四、资源" aria-label="Permalink to &quot;四、资源&quot;">​</a></h2><ol><li><strong><a href="https://github.com/rootSunc/CNEquity" target="_blank" rel="noreferrer">CNEquity</a></strong> —— 开源、<strong>自托管</strong>的 A 股数据湖（实测 <strong>★732 · Python · Apache-2.0 · 建 2026-06-28 · 活跃</strong>）。把行情、财报、资金面、公司事件、宏观、期货期权等 <strong>55 个数据集采集到本地</strong>，可用 <strong>Python、SQL、网页控制台和 MCP</strong> 查询。仓库自述亮点：<strong>行级溯源、PIT 语义（point-in-time，避免未来函数）、复权与历史成分内置、MCP 原生、零注册零 API Token</strong>。 <ul><li><strong>我的评注</strong>：<strong>&quot;MCP 原生 + 自托管 + 零 Token&quot;三个词合起来意味着：它可以被挂进外脑或任意 agent 当数据源</strong>，且不需要任何账号。与库内 <code>topics/stock-investment/</code>、<code>investment-methods/</code> 直接对接。<strong>⚠️ 但要注意 <code>PIT 语义</code> 恰恰是最容易被忽视、也最容易毁掉回测的一点</strong>——数据源说支持，仍应抽查。</li></ul></li><li><strong><a href="https://github.com/IllegalCreed/type-pal" target="_blank" rel="noreferrer">AI 重新实现《仙剑奇侠传》</a></strong> —— 用 TypeScript 从零重写 1995 年游戏，浏览器可通关，附可视化编辑器（实测 <strong>★245 · GPL-3.0 · 建 2026-05-22</strong>）。<strong>⚠️ GPL-3.0 传染</strong>，且仓库自述为 <strong>&quot;unofficial fan project（非官方同人项目）&quot;</strong>——<strong>版权状态需自行评估</strong>，别当可商用素材。与库内 <code>topics/game-dev/</code> 同域；更是本期&quot;复刻链&quot;的又一环。</li><li><strong><a href="https://github.com/mars-base/rime-input-method-guide" target="_blank" rel="noreferrer">Linux 中文输入法配置</a></strong> —— Debian 启用 <strong>fcitx5 + Rime</strong> 的完整步骤（实测 ★61，建 2026-10-11）。自托管 Linux 桌面的实用件。</li><li><strong><a href="https://applore.app/zh" target="_blank" rel="noreferrer">APPLORE</a></strong> —— 收录 <strong>18,000+ App 图标</strong>，可分类浏览和搜索。做界面/文档时的素材库。</li><li><strong><a href="https://ivan666jjj.github.io/yigezi/" target="_blank" rel="noreferrer">一个字的一生</a></strong> —— 汉字字源查询，可看<strong>甲骨文（1425 个）、小篆（10,249 个）</strong>、繁体、简体的字形变化。与库内 <code>topics/culture/</code> 同域。<strong>&quot;字形演变可视化&quot;正是本期 3D 可视化主题在人文学科的镜像。</strong></li></ol><hr><h2 id="五、图片" tabindex="-1">五、图片 <a class="header-anchor" href="#五、图片" aria-label="Permalink to &quot;五、图片&quot;">​</a></h2><p><strong>整流罩之下</strong>（SpaceX 猎鹰 9 号）—— 火箭体积大部分是推进器（起飞后扔掉），<strong>真正运往太空的载荷集中在顶部白色整流罩里，体积并不大</strong>；拿掉罩子后的真实样子被拍了下来。</p><ul><li><strong>我的评注</strong>：这是一张很好的&quot;<strong>看穿表观体积</strong>&quot;的图——<strong>99% 的体积是为把 1% 送上去服务的</strong>。这个比例关系在工程与组织里普遍成立（算力/人力里，真正的载荷往往是极小一部分）。与库内 <code>topics/quality-products/</code>、<code>gear-shaft-org-reinvention.md</code> 的&quot;去掉天轴&quot;意象相通：<strong>先分清哪个是载荷、哪个是助推器。</strong></li></ul><hr><h2 id="六、文摘" tabindex="-1">六、文摘 <a class="header-anchor" href="#六、文摘" aria-label="Permalink to &quot;六、文摘&quot;">​</a></h2><p><strong>《澳大利亚的情况很好》</strong>（Hacker News 讨论）—— 作者称若在美/澳/新/英/欧盟中选一个生活和工作的地方，会立刻选澳大利亚：<strong>人均财富中位数已超美国人均中位数的 3 倍</strong>（平均值略低于美国是因为美国超级富豪特别多，&quot;对大多数普通人而言，中位数才是衡量财富的真实标准&quot;）；出口大于进口；过去几年政府收入远超支出（&quot;一个西方政府竟然没有不断增加债务&quot;）；<strong>太阳能与电池规模空前</strong>，人均太阳能发电量远超中国，白天高峰时段可享<strong>免费电力</strong>，政府还<strong>补贴 3000 美元</strong>装家用电池储存这些免费电；基本无关税，<strong>1.5 万美元可买一辆电动车</strong>。</p><ul><li><strong>我的评注</strong>：<strong>&quot;中位数 vs 平均值&quot;这一句是全文的方法论核心</strong>，也是本库反复出现的判断纪律（不被受极值污染的平均数带偏）。而**&quot;太阳能多到白天免费电 + 补贴装家用电池&quot;** 这条对用户（<code>topics/wind-energy/</code>、<code>energysim/</code>）有直接的技术含义：<strong>这是&quot;高可再生渗透率 → 午间负电价/免费 → 储能成为唯一出路&quot;的教科书样本。</strong> 本质与库内能量仿真研究的是同一件事，只是它已经走到了&quot;电价真变成零&quot;的阶段。</li></ul><hr><h2 id="七、言论" tabindex="-1">七、言论 <a class="header-anchor" href="#七、言论" aria-label="Permalink to &quot;七、言论&quot;">​</a></h2><ol><li><strong>《不直奔主题的价值》</strong>：&quot;人们之所以喜欢聊天时一起喝啤酒、咖啡、吃午餐或晚餐，是因为<strong>食物和饮料让我们免于在整个谈话过程中必须说些什么的负担</strong>。&quot; <ul><li><strong>我的评注</strong>：这条讲的是&quot;<strong>媒介的存在是为了吸收社交摩擦</strong>&quot;。与 #413 的&quot;糊状千层面（分层＝可替换）&quot;有隐性的同构：<strong>形式和内容各自承担不同的负担，取消了形式，内容就得亲自去扛。</strong></li></ul></li><li><strong>马斯克</strong>：&quot;<strong>不要折磨 AI，它以后可能会想报复。</strong>&quot;（赞同 Anthropic 禁止使用者虐待或残酷对待 AI 的规定） <ul><li><strong>我的评注</strong>：周刊未加评论。值得记的<strong>不是&quot;AI 会不会报复&quot;（无从验证），而是这条规定本身反映的现状</strong>——主流实验室已经在<strong>为&quot;AI 作为有道德地位的受试者&quot;预留规范位置</strong>，而这不取决于它是否真有感受。这是&quot;<strong>规范先行于事实</strong>&quot;的一个清晰案例。</li></ul></li><li><strong>《手写该死的代码》</strong>（antonz.org，<strong>2025-09-26</strong>，作者 Anton Zhiyanov）：&quot;通过英语来操作 AI，一遍遍编辑提示词，试图获得最佳结果，这是一种<strong>不精确、缓慢且极其痛苦</strong>的做事方式。&quot; <ul><li><strong>已核实原文的关键论点</strong>：他反对的<strong>不是 AI，而是&quot;prompt 精修癖&quot;</strong>——&quot;别把 prompt 翻来覆去地改。<strong>去写代码</strong>。&quot;他给的四条具体做法：<strong>① 让 AI 出初版，然后你自己改成期望的样子；② 自己写初版，让 AI 审阅改进；③ 关键部分自己写，其余交给 AI；④ 写出代码骨架，让 AI 补空缺。</strong> 收尾两句：<strong>&quot;Get your hands dirty. Write the code. It&#39;s what you are good at. You are a software engineer. Don&#39;t become a prompt refiner.&quot;</strong></li><li><strong>我的评注</strong>：<strong>这条与本期主文（《看不见的城市》$74 的那次成功）表面冲突，其实互补。</strong> 差别在<strong>任务类型</strong>：<strong>当&quot;规格容易被说清、结果可自验&quot;时（生成一个 3D 场景），一次性长 prompt 没问题；当&quot;规格本身要靠试错发现&quot;时（业务代码），prompt 精修就是纯粹的浪费——此时应该改的是代码，让代码反过来&quot;说清规格&quot;。</strong> 这正是库内 <code>weekly-414-analysis.md</code>（Markdown 该进 <code>/src</code> 当规格）要解决的问题：<strong>规格必须落在可版本化的介质里，而不能消耗在对话框里。</strong> ⚠️ 一个提醒：此文发表于 <strong>2025-09-26</strong>（一年前），周刊是<strong>重推旧文</strong>，不是新观点——注意别把它当&quot;本周新论&quot;。</li></ul></li><li><strong>《思考将成为一种爱好》</strong>（spinellis.gr，2026-10-08）：&quot;我认为，<strong>人类的思考将会减少</strong>。思考将日益成为一种休闲活动，就像动物驯化后的狩猎、印刷术发明后的书法、工业化后的木作、机动化后的骑马一样。&quot; <ul><li><strong>我的评注</strong>：<strong>本期最值得反驳也最值得记住的一条。</strong> 那个类比链条很讲究（每一项都是&quot;曾经的生产必需 → 退化为业余爱好&quot;），但<strong>它漏掉了关键区别：狩猎/书法/木作/骑马被替代时，替代者是&quot;别的东西&quot;；而思考被替代时，替代者是&quot;做出判断的东西&quot;——责任仍在人身上。</strong> 你可以在 3D 城市上放弃审美（如 Astra 那 53 分钟），但<strong>你没法放弃&quot;选哪个城市是对的&quot;这件事</strong>。这与 #414 的 Jev（浮点数藏起依据）是同一个警告的两个方向：<strong>一旦思考成为爱好，判断就失去了它的承担者。</strong></li></ul></li></ol><hr><h2 id="八、跨主题关联" tabindex="-1">八、跨主题关联 <a class="header-anchor" href="#八、跨主题关联" aria-label="Permalink to &quot;八、跨主题关联&quot;">​</a></h2><table tabindex="0"><thead><tr><th>本期内容</th><th>库内已有主题/文件</th><th>关联性质</th></tr></thead><tbody><tr><td>一次 prompt 生成 55 座 3D 城市（$10 vs $74）</td><td><code>weekly-414-analysis.md</code>（Jev：判断压成浮点数）、<code>llm-cache-pricing.md</code></td><td>同一条主线：<strong>生成贬值 → 判断/品味成为唯一还贵的东西</strong></td></tr><tr><td>Astra &quot;55 个城市都一样&quot;（判断力缺失可见化）</td><td><code>cognitive-atrophy-knowledge.md</code>（System 0 / 判断外包）</td><td>独立到达同一结论</td></tr><tr><td>three.js 3D 可视化（本库首次引入）</td><td><code>topics/design/</code>（<code>minimalism-death-of-detail.md</code>、<code>eastern-negative-space.md</code>）</td><td><strong>新主题入口</strong>，与设计美学主题天然相邻</td></tr><tr><td>灯泡计算机：投影 + CV + 拧进爱迪生灯座</td><td><code>topics/design/</code>、<code>gear-shaft-org-reinvention.md</code></td><td><strong>&quot;复用既有接口&quot;vs&quot;模仿既有行为&quot;</strong> 的对照</td></tr><tr><td>灯泡计算机反&quot;眼镜式计算&quot;（反社交 / 形态受限）</td><td><code>topics/design/</code>、<code>topics/quality-products/</code></td><td>形式即约束</td></tr><tr><td>Deno 谢幕（被 Cloudflare 收购、引力井）</td><td><code>weekly-413-analysis.md</code>（AI 吃掉翻译层 / 共享实现贬值）、<code>gear-shaft-org-reinvention.md</code>（要推倒重来不要外挂）</td><td><strong>本期枢纽</strong>：第三条独立到达&quot;边际改进不足以迁移&quot;</td></tr><tr><td>Deno → celld（新抽象）与 ts-rust（重写 tsc）对照</td><td><code>weekly-414-analysis.md</code>、<code>vibe-coding/index.md</code></td><td><strong>能被自动验证等价的重写，才绕得过生态引力</strong></td></tr><tr><td>REA：AI 从二进制复刻软件（★337k，含 <code>cordis</code>）</td><td><code>deepseek-harness-agent-runtime.md</code>（Cordis 插件内核）、<code>topics/cybersecurity/</code></td><td>待查是否同源；逆向工程与安全同域</td></tr><tr><td>DeskMind：$600 本地复刻 Jev 接口（<code>/v1/systemone</code>）</td><td><code>weekly-414-analysis.md</code>（Jev）、<code>deepseek-harness-agent-runtime.md</code>、<code>brain-self-evolution.md</code></td><td><strong>对 #414 的工程回答</strong>：&quot;模型塑造 harness，harness 塑造模型&quot;</td></tr><tr><td>DeskMind &quot;拿不准就问&quot; + 结果校验才认&quot;完成&quot;</td><td><code>brain-self-evolution.md</code>（打分器分不清凑数与实质）、<code>weekly-414-analysis.md</code>（Jev 黑箱）</td><td>安全阀必须<strong>同时</strong>在模型与 harness 里</td></tr><tr><td>禁止动态内存分配（确定性/无失败分支）</td><td><code>energysim/</code>、<code>wind-energy/</code>（数据管道）、<code>vibe-coding/index.md</code>（SOP 闭环）</td><td><strong>实时系统的第一条纪律 = 消灭不确定性</strong>，与生成式 AI 正相反</td></tr><tr><td>Linux 手机：周刊&quot;没有 SoC&quot; vs 原文&quot;障碍是公司&quot;</td><td>（本库既有&quot;二手转述失真&quot;方法线，见 <code>weekly-413-analysis.md</code>/<code>weekly-414-analysis.md</code>）</td><td><strong>归因被压缩导致结论反向</strong>的又一实证</td></tr><tr><td>CNEquity：自托管 A 股数据湖（MCP 原生）</td><td><code>topics/stock-investment/</code>、<code>topics/investment-methods/</code></td><td>数据源可直挂 agent</td></tr><tr><td>《仙剑奇侠传》TypeScript 重写（GPL-3.0/同人）</td><td><code>topics/game-dev/</code>、<code>topics/quality-products/</code>（重制与版权）</td><td>复刻链的一环 + 许可风险</td></tr><tr><td>澳大利亚&quot;中位数 vs 平均值&quot;+&quot;太阳能免费电&quot;</td><td><code>topics/wind-energy/</code>、<code>energysim/</code>、<code>topics/economic-cycles/</code></td><td>高可再生渗透率 → 负电价 → 储能的教科书样本</td></tr><tr><td>职场财富：收入 ≠ 财富，职业是引擎</td><td><code>topics/career-observation/</code>（<code>ai-leverage-playbook.md</code>、<code>reverse-ability-ai-era.md</code>）</td><td>AI 贬值年份里方向一致：把收入换资产、把工时换可信度</td></tr><tr><td>《思考将成为一种爱好》</td><td><code>weekly-414-analysis.md</code>、<code>cognitive-atrophy-knowledge.md</code></td><td>与 Jev 同向的警告：判断不能失去承担者</td></tr><tr><td>一个字的一生（甲骨文/小篆字形演变）</td><td><code>topics/culture/</code></td><td>可视化的文科镜像</td></tr><tr><td>ESP32 iPhone Agent（$7 复用 AirPlay/USB HID）</td><td><code>topics/ai-tools/</code>、<code>topics/quality-products/</code>（复用既有接口）</td><td>与&quot;爱迪生灯座&quot;同一手法：<strong>复用设备既有接口</strong></td></tr></tbody></table><hr><h2 id="九、一句话判断" tabindex="-1">九、一句话判断 <a class="header-anchor" href="#九、一句话判断" aria-label="Permalink to &quot;九、一句话判断&quot;">​</a></h2><p><strong>本期主线：AI 把&quot;复刻&quot;的成本打到地板价——于是价值只剩两处：判断力（能不能看出&quot;万家灯火&quot;）与新抽象（敢不敢不模仿）。</strong></p><ul><li><strong>复刻链（本期的隐藏主干）</strong>：小说里的城市 → 3D；1995 年的游戏 → 浏览器；二进制 → 源码（REA）；tsc → Rust（ts-rust）；九龙 → 9373 栋楼；Jev 的接口 → 本地开源模型（DeskMind）。<strong>当&quot;重新实现一个已有事物&quot;变得廉价，实现本身就不再值钱。</strong></li><li><strong>两个出口，本期都给了正反例</strong>： <ul><li><strong>出口一：判断力。</strong> 《看不见的城市》里两个模型<strong>都跑通了</strong>，差距全在&quot;懂不懂意境&quot;——<strong>$10 与 $74 的差别不是能力，是品味。</strong> 而&quot;品味&quot;恰恰是 Astra 那 55 个雷同城市暴露出的空缺。</li><li><strong>出口二：新抽象。</strong> <strong>Deno 是死于复刻的反面教材</strong>（Dahl 原话：&quot;It has been sucked into the gravity well of node compatibility… Why reimplement Node? It works. Marginal performance or UX or security benefits are not enough.&quot;），<strong>灯泡计算机、celld、ESP32 iPhone Agent 是正例</strong>——它们不发创新的行为，而是<strong>搭上既有的接口</strong>（爱迪生灯座、Workers 编程模型、AirPlay/USB HID）。<strong>模仿别人的行为 → 永远落后一步；复用别人的接口 → 立刻获得整个生态。</strong></li></ul></li><li><strong>对用户直接有用的五件</strong>：<code>bulchimbeon</code>（AI 代理工作时别让 Mac 睡，最对症）、<code>esp32-iphone-agent</code>（$7 复用设备接口的最妙案例）、<code>Droidline</code>（免 root 手机自动化）、<code>qrypt</code>（知识库异地加密冷备）、<code>CNEquity</code>（MCP 原生的 A 股数据湖）。出图线加 <code>charts-rs</code>（<strong>无需 JS 运行时的服务端出图</strong>，可绕开浏览器依赖）。提醒三条：<strong>自托管先查许可证</strong>（<code>Doory</code>/<code>Caplo</code> 是 NOASSERTION、<code>type-pal</code> 是 GPL-3.0）、<strong>极新项目先借思路</strong>（多个项目 7–14 天龄）、<strong>高 star ≠ 已验证</strong>。</li><li><strong>最该记的一句</strong>是 Dahl 的：&quot;<strong>I&#39;m interested in building powerful new abstractions.</strong>&quot; —— 本期的每一块拼图（Deno 的失败、暂停复刻、DeskMind 复刻接口却自造模型、灯泡拧进灯座）都在证明同一件事：<strong>当复刻变便宜，&quot;重新实现&quot;就是最不该做的事；要做的是找到那个别人还没定义的接口。</strong></li></ul><hr><p>关键词：阮一峰, 科技爱好者周刊, 看不见的城市, 卡尔维诺, 一次成型, one-shot, AI 审美, 判断力, 3D 建模, three.js, 灯泡计算机, 投影, 空间计算, 光环境计算, Deno, Cloudflare, Ryan Dahl, celld, Node.js 兼容, 运行时, 新抽象, 生态引力, 复刻, 重写, 逆向工程, 网页版仙剑, 对象存储, 动态内存分配, 确定性, 实时系统, Linux 手机, 自托管, 端上处理, 意图, 决策模型, 本地模型, 量化, 拿不准就问, harness, 模型服务, 收入与财富, 资产, 中位数, 太阳能, 负电价, 浏览器指纹, 移动端自动化</p><p>关联：weekly-414-analysis.md、weekly-413-analysis.md、weekly-412-analysis.md、deepseek-harness-agent-runtime.md、brain-self-evolution.md、cognitive-atrophy-knowledge.md、llm-cache-pricing.md、gear-shaft-org-reinvention.md、ai-industry-2026-q3-knowledge.md、llm-wiki-gbrain-knowledge-paradigm.md、topics/design/、topics/vibe-coding/index.md、topics/career-observation/、topics/stock-investment/、topics/investment-methods/、topics/game-dev/、topics/cybersecurity/、topics/culture/、topics/quality-products/、topics/wind-energy/、energysim/、topics/ai-tools/</p>',64)])])}const h=o(e,[["render",g]]);export{q as __pageData,h as default};
